 "content": "def transform(grid):
    """Fill interiors of outlined diagonal V/triangle motifs with color 2."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    colors = {v for row in grid for v in row if v != 0}
    if not colors:
        return out
    marker = max(colors, key=lambda color: sum(v == color for row in grid for v in row))

    # Detect a downward-pointing outline whose apex is the top marker cell.
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            depth = 1
            while r + depth < h:
                left, right = c - depth, c + depth
                if left < 0 or right >= w:
                    break
                if grid[r + depth][left] != marker or grid[r + depth][right] != marker:
                    break
                for x in range(left + 1, right):
                    if out[r + depth][x] == 0:
                        out[r + depth][x] = 2
                depth += 1

    # Detect the opposite orientation: two upper arms converge at a bottom apex.
    for r in range(1, h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            depth = 1
            while r - depth >= 0:
                left, right = c - depth, c + depth
                if left < 0 or right >= w:
                    break
                if grid[r - depth][left] != marker or grid[r - depth][right] != marker:
                    break
                for x in range(left + 1, right):
                    if out[r - depth][x] == 0:
                        out[r - depth][x] = 2
                depth += 1
    return out
